package python

import (
	"path"
	"regexp"

	"github.com/archstats/archstats/core/file"
)

// Conventions are Python's: pytest's file names, and the header Django
// writes on a migration.
func Conventions() file.Conventions {
	return file.Conventions{
		Name:        "python",
		IsTest:      func(p string) bool { return testName.MatchString(path.Base(p)) },
		IsGenerated: djangoMigration.Match,
	}
}

var (
	testName = regexp.MustCompile(`^test_.*\.py$|_test\.py$|^conftest\.py$`)
	// "# Generated by Django 4.2 on 2023-05-01 10:00"
	djangoMigration = regexp.MustCompile(`(?m)^# Generated by Django \d`)
)
